from 写入第二遍 import add
add('28_003',4.5,'16:9，武士头部被长指扣压的侧面特写，白眼在画面左侧，甲指从右上压向中央；固定机位，眼隙、内凹轮廓与指节折角同时清楚。','武士白眼沿黑隙急滑到来者方向，惊惧地认出名字；扣在头顶的甲指向内收紧一寸，椭圆头缘被挤成折弧，几枚深色细点从缝边甩出。武士想把后半句问完，声音却断在气息里；头部再被压低一点，颈侧绷起，白眼僵在被拉长的眼隙边缘。','头部与手指之外为浅冷灰放射图形底，细长线从受压位置向外围展开。','暖白晨光沿甲指尖与头部弧缘形成窄亮，深灰挤压缝与白眼对比清楚，图形底不改实体光向。','甲指节一声低短绞紧，厚重轮廓受压的闷裂细响，武士一口断住的急气。',ja=['魔王欧鉑…！！！','どうしてここに…？！'],tone='武士先失声叫出身份，后一句惊惧急问却说不完整，气息在末尾被压断。',kind='mixed',phase='contact',node={'叙事阶段':'武士认出魔王欧铂，头部受压凹裂','欧铂.揭晓':'姓名由武士明确叫出','武士.状态':'被扣头加压，尚未整体喷裂'},meaning='明确叫名与被扣压凹裂阶段保留，接下一格单次捏碎结果。',motion='甲指持续向内扣，头部向下和内侧压缩，白眼追向后方。',ground='武士与欧铂仍在平台上原接触关系内，控制未松。',characters=['鬼头武士','欧铂'])
add('29_001',5.5,'16:9，低机位双人中全景，武士巨体压在画面左侧近层，欧铂立在右后，抬高扣头的手与头顶喷裂同框；镜头从腰胸线短促上摇到手指，落幅仍保留欧铂完整头肩和双脚站位。','欧铂把扣头的手指收拢到最后位置，武士头部顶端在指间压裂，一束近黑深褐喷溅先向上挑，再向两侧甩开；巨大颈肩随即向左前方沉下，身体失去刚才的撑势。欧铂抬臂高度保持稳定，双脚站稳，披风只在后方掀起小角；他把话低低说完，指节停在收紧的位置，喷裂长线化成几枚飞散点。','背后浅蓝灰云天与暖白透雾晨光，低处米灰尘在脚边成薄层，灰绿平台只在落幅下缘窄处显出。','暖白晨光沿黑甲和披风边缘留亮棱，上方冷白漫射保持裸露胸腹体积，近黑喷溅在亮云前清楚。','一声集中、短实的挤压裂响，接几下细小喷溅风声与巨体沉落的衣肌低响；欧铂声音保持低稳。',ja=['どうやら、俺の言葉を軽く見ていたようだな。'],tone='欧铂低稳地作出判断，语速不急，最后一句向下落定，捏碎后的姿态保持稳定。',kind='mixed',phase='result',node={'叙事阶段':'欧铂单次捏碎武士头部，深色喷裂','武士.状态':'头部压碎，巨体向左前俯沉','欧铂.揭晓':'抬臂与稳立全身关系清楚'},meaning='扣指、头顶深色喷裂、巨体俯斜与欧铂稳立的原格结果保留，不扩写额外解体。',motion='指节向内收至终点，喷裂先上后两侧，巨体向左前下沉，欧铂不随之移步。',ground='欧铂双脚稳踏石面，武士巨体下沉；镜头只展示原作的单次捏碎结果。',characters=['欧铂','鬼头武士'],card={'opening':'欧铂已经听完违令者的惊惧。','beats':['指节收至终点，单次喷裂','巨体俯沉，抬臂与站位保持','低稳说完判断，指节停在收紧处'],'coupling':'暴烈结果与稳定发声、稳立姿态形成反差，力量不靠额外大动作。','landing':'控制结果已定，轮到目睹者承受压力。'})
add('29_002',2,'16:9，董白双眼与额侧的极特写，圆眼居画面中央，刘海压在上沿，嘴在画外；固定机位。','董白双眼僵在睁大的形状里，瞳孔缩成小点，眼睑上缘又绷开极小一截；额侧一滴汗沿鬓边滑到脸侧，鼻梁旁的细汗停住一小拍才向下滚。她迟迟没眨眼，眉间收紧，目光仍锁着欧铂所在的方向。','刘海和脸外缘以外只余浅冷灰图形底，其他背景完全被主体遮住。','晨光在眼中留小而清楚的暖白点，眼睑下方冷灰影加深，汗珠亮面极细。','捏裂余响迅速远去，董白一口压住的短吸气，空地风声变得很轻。',phase='reaction',node={'叙事阶段':'董白目睹捏碎后惊惧出汗','董白.位置':'仍搀扶青，身体未脱离支撑位'},meaning='董白圆眼小瞳、紧眉与汗滴的原格反应保留，不增加说话或放开青。',characters=['董白'])
